def spiral_cells(seed,H,W):
    # outward from seed: up2,right2,down4,left4,up6,right6,down8,left8,up10,right10...
    r,c=seed; dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    cells=[]; L=2; i=0
    while L<=30:
        dr,dc=dirs[i%4]; i+=1
        for _ in range(L):
            r+=dr; c+=dc
            if 0<=r<H and 0<=c<W: cells.append((r,c))
            else: return cells,'exit'
        L+=2
    return cells,'done'

for dnum in [1,2,3]:
    inp=np.array(G[f'Demo pair {dnum} input']); out=np.array(G[f'Demo pair {dnum} output'])
