    seed=[(r,c) for r in range(H) for c in range(W) if inp[r,c]==3][0]
    cells,st=spiral_cells(seed,H,W)
    # find innermost blocking 2 (closest to seed along path order from the end)
    idx={cell:i for i,cell in enumerate(cells)}
    blocks=[(idx[cell],cell) for cell in cells if inp[cell]==2]
